using System;using System.Linq;using System.IO;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class FacadeInspect {
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static string Read(){var s=SceneManager.GetActiveScene();var map=s.GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");var rows=map.GetComponentsInChildren<MeshRenderer>().Where(r=>new[]{"B02","B03","B04","B05","B06","B07"}.Any(id=>r.name=="AB01_"+id+".001")).Select(r=>{var mesh=r.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices.Select(p=>r.transform.TransformPoint(p)).ToArray();bool north=!r.name.Contains("B06")&&!r.name.Contains("B07");float edge=north?r.bounds.max.z:r.bounds.min.z;return new{r.name,min=V(r.bounds.min),max=V(r.bounds.max),materials=r.sharedMaterials.Select(m=>m.name).ToArray(),colliders=r.GetComponentsInChildren<Collider>().Select(c=>new{c.name,type=c.GetType().Name}),strips=Enumerable.Range(0,mesh.subMeshCount).Select(i=>new{mat=r.sharedMaterials[i].name,points=mesh.GetTriangles(i).Distinct().Select(j=>v[j]).Where(p=>p.y<3.6f&&Mathf.Abs(p.z-edge)<1.4f).Select(p=>new[]{Mathf.Round(p.x*100)/100,Mathf.Round(p.y*100)/100,Mathf.Round(p.z*100)/100}).Distinct(new VE()).ToArray()})};}).ToArray();string j=JsonConvert.SerializeObject(new{scene=s.path,dirty=s.isDirty,rows});File.WriteAllText("Docs/MapLayout/Myeongji/facade_inspection.json",j);return string.Join("\n",rows.Select(r=>r.name+": "+string.Join("; ",r.strips.Where(m=>m.mat.Contains("Glass")).SelectMany(m=>m.points).GroupBy(v=>v[2]).Select(g=>"z="+g.Key+" x="+g.Min(v=>v[0])+".."+g.Max(v=>v[0])+" y="+g.Min(v=>v[1])+".."+g.Max(v=>v[1])))));}
 class VE:System.Collections.Generic.IEqualityComparer<float[]>{public bool Equals(float[]a,float[]b)=>a.SequenceEqual(b);public int GetHashCode(float[]a)=>a[0].GetHashCode()^a[1].GetHashCode()^a[2].GetHashCode();}}
